// 6 - Copy your engagement letter template (a Google Doc with {{TAGS}}),
// fill in this client, and export it as a PDF for the welcome email.
const cfg = $('0 - Config: Your Settings').first().json;
const lead = $('1 - Lawmatics: Website, Phone or Referral Lead You Mark Ready to Engage').first().json.body;
const matter = $('4 - Clio: Open the Estate Planning Matter').first().json.data;
const drive = 'googleDriveOAuth2Api';
const docs = 'googleDocsOAuth2Api';
const clientName = lead.first_name + ' ' + lead.last_name;
const today = new Date().toLocaleDateString('en-US', { timeZone: 'America/New_York', year: 'numeric', month: 'long', day: 'numeric' });

const copy = await this.helpers.httpRequestWithAuthentication.call(this, drive, {
  method: 'POST',
  url: 'https://www.googleapis.com/drive/v3/files/' + cfg.engagement_letter_template_id + '/copy',
  body: { name: lead.last_name + ' - Engagement Letter - ' + matter.display_number, parents: [cfg.client_folder_id] },
  json: true,
});

const fills = { CLIENT_FULL_NAME: clientName, MATTER_NUMBER: matter.display_number, MATTER_TYPE: lead.matter_type, DATE: today };
await this.helpers.httpRequestWithAuthentication.call(this, docs, {
  method: 'POST',
  url: 'https://docs.googleapis.com/v1/documents/' + copy.id + ':batchUpdate',
  body: { requests: Object.entries(fills).map(([tag, value]) => ({
    replaceAllText: { containsText: { text: '{{' + tag + '}}', matchCase: true }, replaceText: String(value || '') },
  })) },
  json: true,
});

const pdf = await this.helpers.httpRequestWithAuthentication.call(this, drive, {
  method: 'GET',
  url: 'https://www.googleapis.com/drive/v3/files/' + copy.id + '/export',
  qs: { mimeType: 'application/pdf' },
  encoding: 'arraybuffer',
  json: false,
});
const binary = await this.helpers.prepareBinaryData(Buffer.from(pdf), copy.name + '.pdf', 'application/pdf');
return [{ json: { engagement_letter_doc: 'https://docs.google.com/document/d/' + copy.id }, binary: { engagement_letter: binary } }];

