// 9 - One copy of each template the client needs, saved in the client's Drive
// folder, every {{TAG}} replaced with Claude's fill-in. Your template wording
// is never rewritten: only the blanks change.
const cfg = $('0 - Config: Your Settings').first().json;
const lead = $('1 - Lawmatics: Website, Phone or Referral Lead You Mark Ready to Engage').first().json.body;
const matter = $('4 - Clio: Open the Estate Planning Matter').first().json.data;
const result = $json.output;
const templates = {
  will: cfg.will_template_id,
  revocable_trust: cfg.trust_template_id,
  durable_poa: cfg.poa_template_id,
  health_care_surrogate: cfg.surrogate_template_id,
};
const names = { will: 'Will', revocable_trust: 'Revocable Trust', durable_poa: 'Durable POA', health_care_surrogate: 'Health Care Surrogate' };

const drafts = [];
for (const doc of result.documents_needed || []) {
  if (!templates[doc]) continue;
  const copy = await this.helpers.httpRequestWithAuthentication.call(this, 'googleDriveOAuth2Api', {
    method: 'POST',
    url: 'https://www.googleapis.com/drive/v3/files/' + templates[doc] + '/copy',
    body: { name: lead.last_name + ' - ' + names[doc] + ' - FIRST DRAFT - ' + matter.display_number, parents: [cfg.client_folder_id] },
    json: true,
  });
  await this.helpers.httpRequestWithAuthentication.call(this, 'googleDocsOAuth2Api', {
    method: 'POST',
    url: 'https://docs.googleapis.com/v1/documents/' + copy.id + ':batchUpdate',
    body: { requests: Object.entries(result.fields || {}).map(([tag, value]) => ({
      replaceAllText: { containsText: { text: '{{' + tag + '}}', matchCase: true }, replaceText: String(value || '[CONFIRM WITH CLIENT]') },
    })) },
    json: true,
  });
  drafts.push({ document: names[doc], url: 'https://docs.google.com/document/d/' + copy.id });
}
return [{ json: { client: lead.first_name + ' ' + lead.last_name, matter: matter.display_number, drafts, open_questions: result.open_questions || [] } }];

