// 13 - Clients quiet mid-matter: waiting on a signing appointment, missing
// documents or an unpaid retainer, with nothing new on the matter for your
// set number of days. Reminders go out on that day, twice that and three
// times that, then the paralegal is told to call instead.
const QUIET_DAYS = Number('PASTE-YOUR-QUIET-DAYS');       // days of silence before the first reminder
const BOOKING_LINK = 'PASTE-YOUR-SIGNING-BOOKING-LINK';   // your Google Calendar appointment page
const FIRM = 'PASTE-YOUR-FIRM-NAME';
const PARALEGAL = 'PASTE-YOUR-PARALEGAL-EMAIL';
// Left side: your Clio matter stage names, exactly as they appear in Clio.
const STAGES = {
  'Signing Appointment': 'signing',
  'Waiting on Documents': 'documents',
  'Retainer Unpaid': 'retainer',
};
const ask = {
  signing: 'your documents are ready to sign. Please pick a signing time that works for you here: ' + BOOKING_LINK,
  documents: 'we are still waiting on a few documents from you before we can finish your plan. Reply to this email with any questions about what we need.',
  retainer: 'your retainer is still open on our side, so work on your plan is paused. Reply here or call the office and we will help you with payment.',
};
const out = [];
for (const m of $json.data || []) {
  const reason = STAGES[(m.matter_stage || {}).name];
  const email = ((m.client || {}).primary_email_address) || '';
  if (!reason || !email) continue;
  const days = Math.floor((Date.now() - new Date(m.updated_at).getTime()) / 86400000);
  if (days < QUIET_DAYS || days % QUIET_DAYS !== 0) continue;
  const round = days / QUIET_DAYS;
  if (round > 4) continue; // three client reminders, then one call-them note to the paralegal
  const first = (m.client.name || '').split(' ')[0];
  out.push({ json: {
    matter: m.display_number,
    client_name: m.client.name,
    client_email: email,
    to: round > 3 ? PARALEGAL : email,
    reason,
    days_quiet: days,
    reminder_number: round,
    subject: round > 3 ? 'Please call: ' + m.client.name + ', quiet on ' + reason : 'A quick next step on your estate plan',
    message: round > 3
      ? 'Third reminder already sent. Please call the client.\n\nClient: ' + m.client.name + ' (' + email + ')\nMatter: ' + m.display_number + '\nWaiting on: ' + reason + '\nQuiet for ' + days + ' days.'
      : 'Hi ' + first + ',\n\nA quick note from ' + FIRM + ': ' + ask[reason] + '\n\nThank you,\n' + FIRM,
    paralegal_note: round > 3 ? 'Third reminder already sent. Please call the client.' : 'Reminder ' + round + ' sent automatically.',
  }});
}
return out;

